from pathlib import Path
import subprocess
import sys
import tomllib

import pytest

from scripts.check_connector_imports import check_connector_imports

ROOT = Path(__file__).resolve().parents[2]
HEADER = "# AI-generated file.\n# Generated by Codex(GPT) in 2026-10-30 15:34.\n"


@pytest.mark.parametrize(
    ("source", "target"),
    [("contracts", "runtime"), ("contracts", "spi"), ("agents", "runtime"), ("sdk", "psycopg"), ("connectors", "httpx")],
)
def test_import_linter_rejects_forbidden_dependencies(tmp_path: Path, source: str, target: str) -> None:
    """在临时工程注入跨层或越权导入，实际调用 import-linter 检查。"""
    pyproject = (ROOT / "pyproject.toml").read_text(encoding="utf-8")
    for package in tomllib.loads(pyproject)["tool"]["importlinter"]["root_packages"]:
        directory = tmp_path / package
        directory.mkdir()
        (directory / "__init__.py").write_text(HEADER, encoding="utf-8")
    (tmp_path / "pyproject.toml").write_text(pyproject, encoding="utf-8")
    (tmp_path / source / "violation.py").write_text(HEADER + f"import {target}\n", encoding="utf-8")
    result = subprocess.run(
        [str(Path(sys.executable).with_name("lint-imports")), "--no-cache"],
        cwd=tmp_path, capture_output=True, text=True, check=False,
    )
    assert result.returncode != 0
    assert "BROKEN" in result.stdout, result.stdout + result.stderr


@pytest.mark.parametrize("statement", ["import urllib.request", "from urllib import request", "from http.client import HTTPConnection"])
def test_connector_submodule_bypasses_are_rejected(tmp_path: Path, statement: str) -> None:
    """同时覆盖完整模块导入与 from-import 写法。"""
    (tmp_path / "connector.py").write_text(HEADER + statement + "\n", encoding="utf-8")
    assert len(check_connector_imports(tmp_path)) == 1


def test_connector_url_parsing_is_allowed(tmp_path: Path) -> None:
    """urllib.parse 仅处理 URL，本身不访问网络，应被允许。"""
    (tmp_path / "connector.py").write_text(HEADER + "from urllib.parse import urlparse\n", encoding="utf-8")
    assert check_connector_imports(tmp_path) == []
